CommitDate: Tue Oct 29 17:58:30 2024 +0000

    Bug 1925383 - Show a 20 years donation appeal inside a Thunderbird tab. r=sancus


    **How to test**
    - On startup a new tab with the donation appeal should open up and grab focus.
    - Clicking on the donation button should open a browser page with the same page but the donation dialog opened.
    - To test it again after first launch, update your `app.donation.eoy.version` pref back to 6.

    Differential Revision: https://phabricator.services.mozilla.com/D227116

diff --git a/mail/app/profile/all-thunderbird.js b/mail/app/profile/all-thunderbird.js
index c2af4a331fc..f024ff7d861 100644
--- a/mail/app/profile/all-thunderbird.js
+++ b/mail/app/profile/all-thunderbird.js
@@ -1373,9 +1373,9 @@ pref("services.sync.engine.servers", true);
 #endif

 // Donation appeal.
-pref("app.donation.eoy.version", 6);
+pref("app.donation.eoy.version", 7);
 pref("app.donation.eoy.version.viewed", 0);
-pref("app.donation.eoy.url", "https://www.thunderbird.net/thunderbird/128.0/appeal/");
+pref("app.donation.eoy.url", "https://updates.thunderbird.net/thunderbird/128.0/nov24/");

 // IMAP-JS disabled, Bug 1707547.
 pref("mailnews.imap.jsmodule", false);
diff --git a/mail/base/content/messenger.js b/mail/base/content/messenger.js
index 658cea0a08e..dd55bd0976e 100644
--- a/mail/base/content/messenger.js
+++ b/mail/base/content/messenger.js
@@ -379,10 +379,28 @@ var gMailInit = {
    */
   showEOYDonationAppeal() {
     const url = Services.prefs.getStringPref("app.donation.eoy.url");
-    const protocolSvc = Cc[
-      "@mozilla.org/uriloader/external-protocol-service;1"
-    ].getService(Ci.nsIExternalProtocolService);
-    protocolSvc.loadURI(Services.io.newURI(url));
+    let tabmail = document.getElementById("tabmail");
+
+    if (!tabmail) {
+      tabmail = Services.wm
+        .getMostRecentWindow("mail:3pane")
+        ?.document.getElementById("tabmail");
+    }
+
+    // Fall back to opening a browser window if we don't have a tabmail.
+    if (!tabmail) {
+      const protocolSvc = Cc[
+        "@mozilla.org/uriloader/external-protocol-service;1"
+      ].getService(Ci.nsIExternalProtocolService);
+      protocolSvc.loadURI(Services.io.newURI(url));
+    } else {
+      tabmail.openTab("contentTab", {
+        url,
+        background: false,
+        linkHandler: "single-page",
+      });
+      tabmail.ownerGlobal.focus();
+    }

     const currentEOY = Services.prefs.getIntPref("app.donation.eoy.version", 1);
     Services.prefs.setIntPref("app.donation.eoy.version.viewed", currentEOY);
